/* Maximum Remaining Length value: 268435455, encoded FF FF FF 7F. */
#define MQTT_MAX_REMAINING_LENGTH 268435455u

/* Maximum fixed-header prefix length: 1 type byte + 4 Remaining Length bytes. */
#define MQTT_MAX_HEADER_PREFIX 5u

/* Type field values (byte 1, bits 7-4). 0 and 15 are reserved and forbidden. */
typedef enum mqtt_packet_type {
    MQTT_PKT_CONNECT = 1,
    MQTT_PKT_CONNACK = 2,
    MQTT_PKT_PUBLISH = 3,
    MQTT_PKT_PUBACK = 4,
    MQTT_PKT_PUBREC = 5,
    MQTT_PKT_PUBREL = 6,
    MQTT_PKT_PUBCOMP = 7,
    MQTT_PKT_SUBSCRIBE = 8,
    MQTT_PKT_SUBACK = 9,
    MQTT_PKT_UNSUBSCRIBE = 10,
    MQTT_PKT_UNSUBACK = 11,
    MQTT_PKT_PINGREQ = 12,
    MQTT_PKT_PINGRESP = 13,
    MQTT_PKT_DISCONNECT = 14
} mqtt_packet_type;

/* Outcome of a framing/parse attempt. On INCOMPLETE nothing is written to the
 * output structure and the caller buffers more bytes; the byte count already
 * consumed must remain 0. On NOMEM the caller reports a transient error in the
 * same result domain (for example when its own copy of a slice fails) and
 * closes only that connection. */
typedef enum mqtt_decode_result {
    MQTT_DECODE_NOMEM = -2,
    MQTT_DECODE_INVALID = -1,
    MQTT_DECODE_INCOMPLETE = 0,
    MQTT_DECODE_COMPLETE = 1
} mqtt_decode_result;

/* Decoded fixed header plus the borrowed body slice. */
typedef struct mqtt_frame {
    uint8_t type;              /* byte 1 bits 7-4; 1..14 */
    uint8_t flags;             /* byte 1 bits 3-0; PUBLISH carries DUP/QoS/RETAIN */
    uint32_t remaining_length; /* decoded Remaining Length (variable header + payload) */
    size_t header_len;         /* fixed header size in bytes: 1 + number of Remaining Length bytes */
    size_t total_len;          /* header_len + remaining_length: whole packet size in bytes */
    const uint8_t *body;       /* borrowed pointer to remaining_length bytes of variable header + payload */
} mqtt_frame_t;

/* Outcome of mqtt_decode_connect(). Values >= 0 that are not MQTT_CONNECT_OK
 * are exactly the CONNACK return code to send before closing. */
typedef enum mqtt_connect_result {
    MQTT_CONNECT_CLOSE = -1,            /* close the connection without sending a CONNACK */
    MQTT_CONNECT_OK = 0,                /* CONNACK 0x00 (session present 0), connection accepted */
    MQTT_CONNECT_REFUSE_PROTOCOL = 1,   /* CONNACK 0x01 unacceptable protocol version, then close */
    MQTT_CONNECT_REFUSE_IDENTIFIER = 2  /* CONNACK 0x02 identifier rejected, then close */
} mqtt_connect_result;

/* Decoded CONNECT. All slices borrow the frame body and are valid only while
 * the caller keeps those bytes. will_flag is always 0 for an accepted CONNECT
 * because a CONNECT with a Will is closed. username/password are parsed and
 * validated but never used for authentication. */
typedef struct mqtt_connect {
    const char *client_id;   /* borrowed; 1..65535 UTF-8 bytes, no U+0000 */
    size_t client_id_len;
    const char *username;    /* borrowed, NULL and 0 when the flag is clear */
    size_t username_len;
    const char *password;    /* borrowed, NULL and 0 when the flag is clear */
    size_t password_len;
    uint16_t keep_alive;     /* seconds; 0 disables the keep alive mechanism */
    uint8_t protocol_level;  /* 4 on success */
    uint8_t clean_session;   /* 1 on success */
    uint8_t will_flag;       /* 0 on success */
    uint8_t has_username;
    uint8_t has_password;
} mqtt_connect_t;

/* Decoded inbound PUBLISH. topic and payload borrow the frame body. qos, dup
 * and retain are the raw flag fields so the caller can enforce the supported
 * subset: the codec itself rejects only QoS 3, DUP with QoS 0 and structural
 * problems, and passes well-formed but unsupported QoS/retain values through. */
typedef struct mqtt_publish {
    const char *topic;       /* borrowed; 1..65535 UTF-8 bytes, no wildcard */
    size_t topic_len;
    const uint8_t *payload;  /* borrowed; payload_len may be 0 */
    size_t payload_len;
    uint8_t qos;
    uint8_t dup;
    uint8_t retain;
} mqtt_publish_in;

/* Cursor over the SUBSCRIBE payload pairs. Iteration may be repeated from the
 * same cursor position by copying the cursor value. */
typedef struct mqtt_subscribe_it {
    const uint8_t *cur;   /* next unread payload byte */
    const uint8_t *end;   /* one past the last payload byte */
    uint16_t packet_id;   /* non-zero identifier from the SUBSCRIBE variable header */
} mqtt_subscribe_it;

/* mqtt_subscribe_next() results. */
#define MQTT_SUB_NEXT_OK 0       /* one pair was written to the output parameters */
#define MQTT_SUB_NEXT_END 1      /* payload exhausted cleanly */
#define MQTT_SUB_NEXT_INVALID (-1) /* malformed pair: close the connection */

/*
 * Decode the fixed header at the start of data[0..len) into *out.
 * Returns MQTT_DECODE_INCOMPLETE when fewer bytes are available than the
 * fixed header needs, MQTT_DECODE_INVALID when the type is 0/15, when the
 * Remaining Length needs more than 4 bytes, or when the reserved flag pattern
 * of the type is violated, MQTT_DECODE_COMPLETE otherwise. On COMPLETE,
 * out->header_len is the fixed-header size and out->total_len is the whole
 * packet size, so the caller may dispatch only when len >= out->total_len.
", "source": "/home/ljf/SpecForge/runs/paper/round_01/mqtt_01/logs/03_specs/api/tools_012.json"}]

