 *   owner thread only : broker_session_fd, broker_session_wake_fd,
 *                       broker_session_input, broker_session_state,
 *                       broker_session_set_state, broker_session_send_pending,
 *                       broker_session_has_pending, broker_session_drain_wake
 *   any thread        : broker_session_enqueue, broker_session_should_stop,
 *                       broker_stop_all, broker_wait_all
 *   owner thread of the session argument : broker_session_connect,
 *                       broker_subscribe, broker_publish
 *
 * Wake-up protocol (producer / recipient)
 * ---------------------------------------
 * Producers never touch the client socket.  broker_session_enqueue() appends
 * the bytes to the session output FIFO under the session output lock and then
 * writes one byte to the session wake pipe, so a recipient that is idle in
 * poll() makes progress even when it never sends anything itself.  The
 * recipient drains the wake pipe (broker_session_drain_wake) and only
 * afterwards tests broker_session_has_pending(), which makes the wake-up
 * unfailable: an append performed before the drain is either observed by that
 * pending test or leaves one byte readable in the pipe for the next poll().
 *
 * Lock order is broker mutex -> session output lock.  No socket call is made
 * while the broker mutex is held; the only socket call made while the session
 * output lock is held is the single non-blocking send of
 * broker_session_send_pending().  The per-session stop flag is guarded by the
 * session output lock, so a producer can request closure from inside a broker
 * mutex critical section (broker_publish) without re-entering that mutex.
 *
 * Ownership
 * ---------
 * The broker copies every byte it must keep: client identifiers and topic
 * filter strings.  Topic and payload slices passed to broker_publish() are
 * borrowed for the duration of that call only: the message is encoded once
 * into the broker's private scratch buffer and the resulting bytes are copied
 * into each matching session's output FIFO.
 */

#include <stddef.h>
#include <stdint.h>

#include "buf.h"

/* Opaque broker aggregate: mutex, condition variable, session registry,
 * subscription table, routing scratch buffer and live-session count. */
typedef struct broker broker_t;

/* Opaque per-connection object.  Created and registered by
