/* ---------------------------------------------------------- mqtt_wire --- */

static void decode_case(const char *hex, mqtt_decode_result want, const char *label)
{
    unsigned char buf[64];
    mqtt_frame_t fr;
    int n = hex_to_bytes(hex, buf, sizeof buf);
    mqtt_decode_result got;

    if (n <= 0) {
        check_true(label, 0);
        return;
    }
    memset(&fr, 0, sizeof fr);
    got = mqtt_frame_decode(buf, (size_t)n, &fr);
    check_int(label, (long)got, (long)want);
}

static void test_frame_decode(void)
{
    unsigned char connect[32];
    unsigned char body[32];
    mqtt_frame_t fr;
    int n;

    /* Accepted CONNECT: 10 0D 00 04 "MQTT" 04 02 00 3C 00 01 'a' */
    n = hex_to_bytes("100D00044D5154540402003C000161", connect, sizeof connect);
    check_int("decode-connect-size", n, 15);
    memset(&fr, 0, sizeof fr);
    check_int("decode-connect-result", mqtt_frame_decode(connect, (size_t)n, &fr),
              MQTT_DECODE_COMPLETE);
    check_int("decode-connect-type", fr.type, MQTT_PKT_CONNECT);
    check_int("decode-connect-flags", fr.flags, 0);
    check_int("decode-connect-rl", (long)fr.remaining_length, 13);
    check_int("decode-connect-header", (long)fr.header_len, 2);
    check_int("decode-connect-total", (long)fr.total_len, 15);
    check_true("decode-connect-body", fr.body == connect + 2);
    hex_to_bytes("00044D5154540402003C000161", body, sizeof body);
    check_mem("decode-connect-body-bytes", fr.body, body, 13);

    /* Fixed header present but the body is not yet: still COMPLETE, the caller
     * compares total_len against the available byte count. */
    decode_case("30070003612F", MQTT_DECODE_COMPLETE, "decode-publish-header-only");

    /* Truncated fixed header. */
    decode_case("30", MQTT_DECODE_INCOMPLETE, "decode-truncated-rl");
    decode_case("30FF", MQTT_DECODE_INCOMPLETE, "decode-truncated-rl-cont");

    /* Reserved types and reserved flags. */
    decode_case("0000", MQTT_DECODE_INVALID, "decode-type-zero");
    decode_case("F000", MQTT_DECODE_INVALID, "decode-type-fifteen");
    decode_case("110D00044D5154540402003C000161", MQTT_DECODE_INVALID,
                "decode-connect-reserved-flags");
    decode_case("8008000A0003612F6202", MQTT_DECODE_INVALID,
                "decode-subscribe-bad-flags");
    /* Remaining Length needing more than four bytes. */
    decode_case("30FFFFFFFF7F", MQTT_DECODE_INVALID, "decode-rl-too-long");
    /* Maximum Remaining Length FF FF FF 7F. */
    {
        int m = hex_to_bytes("30FFFFFF7F", connect, sizeof connect);

        check_int("decode-max-rl-size", m, 5);
        memset(&fr, 0, sizeof fr);
        check_int("decode-max-rl-result", mqtt_frame_decode(connect, (size_t)m, &fr),
                  MQTT_DECODE_COMPLETE);
        check_int("decode-max-rl-value", (long)fr.remaining_length, 268435455);
        check_int("decode-max-rl-header", (long)fr.header_len, 5);
        check_int("decode-max-rl-total", (long)fr.total_len, 268435460);
    }
}

static void test_utf8(void)
{
    check_int("utf8-empty", mqtt_utf8_valid("", 0), 1);
    check_int("utf8-ascii", mqtt_utf8_valid("abc", 3), 1);
