import json, os
w='/work/files/'
def load(p): return json.load(open(w+p))
def fix(sig):
    if isinstance(sig,str) and not sig.rstrip().endswith(';'):
        return sig.rstrip()+';'
    return sig
for h,c,out in [('util_h.json','util_c.json','util.json'),('codec_h.json','codec_c.json','codec.json')]:
    H=load(h); C=load(c)
    m={'KIND':'FILE_SPEC','FILE':C['FILE'],'HEADER':H['HEADER']}
    for src in (H,C):
        for k,v in src.items():
            if k in ('KIND','FILE','HEADER','SOURCE'): continue
            if k in m and isinstance(m[k],list) and isinstance(v,list): m[k]=m[k]+v
            elif k not in m: m[k]=v
    m['SOURCE']=C['SOURCE']
    for blk in ('HEADER','SOURCE'):
        for it in m[blk]['INTERFACE']:
            it['SIGNATURE']=fix(it['SIGNATURE'])
    json.dump(m,open(w+out,'w'),indent=2)
    os.remove(w+h); os.remove(w+c)
    print(out,'written; header funcs',len(m['HEADER']['INTERFACE']),'source funcs',len(m['SOURCE']['INTERFACE']))
EOF
