import json,glob,re
def fix(refs):
    out=[]
    for r in refs:
        if r.startswith('facts.json#'): continue
        if r.endswith('.h'): continue
        m=re.fullmatch(r'scope\.json#(R\d+)', r)
        if m:
            out.append(m.group(1)); continue
        if r.startswith('scope.json#'): continue
        out.append(r)
    return out
n=0
for p in glob.glob('files/*.json')+['module_spec.json']:
    d=json.load(open(p))
    changed=False
    def walk(o):
        global changed
        if isinstance(o,dict):
            for k,v in o.items():
                if k=='TRACE_REFS' and isinstance(v,list):
                    nv=fix(v)
                    if nv!=v:
                        o[k]=nv; changed=True
                else: walk(v)
        elif isinstance(o,list):
            for x in o: walk(x)
    walk(d)
    if changed:
        json.dump(d,open(p,'w'),indent=2); n+=1
        print('fixed',p)
print('files changed',n)
