def rl(n):
    out=[]
    while True:
        b=n%128; n//=128
        if n: out.append(b|0x80)
        else:
            out.append(b); break
    return bytes(out)
def connect(cid, keepalive=60, flags=0x02, level=4):
    vh=b'\x00\x04MQTT'+bytes([level,flags])+keepalive.to_bytes(2,'big')
    pl=len(cid).to_bytes(2,'big')+cid
    body=vh+pl
    return bytes([0x10])+rl(len(body))+body
print(connect(b'c2').hex(' ').upper(), 'len', len(connect(b'c2')))
print(connect(b'sensor-1').hex(' ').upper(), 'len', len(connect(b'sensor-1')))
