import json,os
t=json.load(open('traceability.json'))
def resolve(ref):
    f,ptr=ref.split('#',1)
    if not os.path.exists(f): return f"MISSING FILE {f}"
    d=json.load(open(f))
    if ptr in ('','/'): return None
    cur=d
    for part in ptr.strip('/').split('/'):
        part=part.replace('~1','/').replace('~0','~')
        if isinstance(cur,list):
            try: cur=cur[int(part)]
            except Exception: return f"BAD INDEX {ref}"
        elif isinstance(cur,dict):
            if part not in cur: return f"BAD KEY {ref} (key {part})"
            cur=cur[part]
        else: return f"NOT CONTAINER {ref}"
    return None
errs=[]
seen=set()
for r in t['requirements']:
    seen.add(r['requirement_id'])
    for ref in r['spec_refs']+r['test_ids']:
        e=resolve(ref)
        if e: errs.append((r['requirement_id'],e))
    if not r['spec_refs'] or not r['test_ids']: errs.append((r['requirement_id'],'empty refs'))
for pc in t['processing_chain']:
    for ref in pc['spec_refs']:
        e=resolve(ref)
        if e: errs.append((pc['id'],e))
for ed in t['engineering_decisions']:
    e=resolve(ed['spec_ref'])
    if e: errs.append(('eng',e))
scope=json.load(open('scope.json'))
ids=[x['id'] for x in scope['requirements']]
print('scope ids',ids)
print('covered',sorted(seen))
print('missing',[i for i in ids if i not in seen])
facts=set(f['id'] for f in json.load(open('facts.json'))['facts'])
for r in t['requirements']:
    bad=[f for f in r['fact_ids'] if f not in facts]
    if bad: errs.append((r['requirement_id'],f'bad facts {bad}'))
print('ERRORS', len(errs))
for e in errs: print(e)
