static void group_shutdown(void)
{
    srv s;
    int c;
    uint8_t buf[64];
    int eof = 0;
    int n;

    printf("-- group shutdown\n");
    srv_start(&s);

    c = connect_to(s.port);
    send_connect(c, "bye", 0x02, 4);
    expect_connack(c, 0x00, "CONNACK before shutdown");

    kill(s.pid, SIGTERM);
    n = read_to_eof(c, buf, sizeof buf, 8000, &eof);
    CHECK(eof, "SIGTERM must close the client session (read %d bytes, eof=%d)", n, eof);
    CHECK(n == 0, "SIGTERM must not send extra bytes (got %d)", n);
    close(c);
    srv_finish(&s);
}

