BIN := mqtt_broker

SRCS := src/broker.c src/codec.c src/main.c src/net.c src/session.c src/topic.c src/util.c
LIB_SRCS := $(filter-out src/main.c,$(SRCS))
OBJS := $(patsubst src/%.c,$(BUILD)/%.o,$(SRCS))
LIB_OBJS := $(patsubst src/%.c,$(BUILD)/%.o,$(LIB_SRCS))

TEST_SRCS := tests/wire_test.c tests/unit_test.c tests/cli_test.c
TEST_BINS := $(patsubst tests/%.c,$(BUILD)/%,$(TEST_SRCS))

.PHONY: all clean test sanitize runtest

all:
	@mkdir -p build
	@printf 'normal\n' > $(CONFIG_FILE)
	@$(MAKE) --no-print-directory $(BIN)

sanitize:
	@mkdir -p build
	@printf 'sanitize\n' > $(CONFIG_FILE)
	@$(MAKE) --no-print-directory BUILD=build/san \
		SANFLAGS='$(SAN_BASE)' LDSAN='$(SAN_LINK)' $(BIN)

$(BIN): $(OBJS)
	$(CC) $(CFLAGS) $(SANFLAGS) $(LDSAN) -o $@ $(OBJS) $(LDLIBS)

$(BUILD)/%.o: src/%.c
	@mkdir -p $(dir $@)
	$(CC) $(CPPFLAGS) $(CFLAGS) $(SANFLAGS) -c $< -o $@

test:
	@cfg=$$(cat $(CONFIG_FILE) 2>/dev/null || printf 'normal'); \
	if [ "$$cfg" = "sanitize" ]; then \
		echo "== testing current sanitizer build =="; \
		$(MAKE) --no-print-directory BUILD=build/san \
			SANFLAGS='$(SAN_BASE)' LDSAN='$(SAN_LINK)' runtest; \
	else \
		echo "== testing current normal build =="; \
		$(MAKE) --no-print-directory runtest; \
	fi

runtest: $(TEST_BINS) $(BIN)
	@for t in $(TEST_BINS); do \
		echo "-- $$t"; \
		$$t ./$(BIN) || exit 1; \
	done
