/*
 * broker.h - MQTT 3.1.1 broker protocol core.
 *
 * The broker owns a registry of sessions. It performs no I/O of its own: the
 * execution layer fills a session's receive buffer and drains its output
 * buffer, while the broker frames packets out of that receive buffer, applies
 * the protocol policy and queues complete responses into the output buffer.
 *
 * Ownership:
 *   - broker_accept() takes ownership of the accepted descriptor on success
 *     only; on failure the descriptor is still owned by the caller.
 *   - Every session in the registry is owned by the broker and destroyed by
 *     broker_destroy() or broker_reap(). Callers only borrow session pointers.
 *   - A session pointer returned by broker_session_at() is invalidated by the
 *     next broker_reap(), broker_accept() or broker_destroy() call.
 *
 * Error isolation: a malformed or unsupported packet closes only the
 * connection that delivered it. A failure to queue output for one fan-out
 * recipient closes only that recipient.
 */
#ifndef MQTT_BROKER_BROKER_H
#define MQTT_BROKER_BROKER_H

#include <stddef.h>

#include "session.h"

/* Outcome of handling one packet inside a session. */
enum broker_result {
    BROKER_CONTINUE = 0, /* session stays usable */
    BROKER_CLOSE = 1     /* session is or must be closed */
};

/* Opaque registry of active connections. */
struct broker;

/* Create an empty registry. Returns 0 on success, -1 on allocation failure. */
int broker_create(struct broker **out_broker);

/* Destroy every session still in the registry, then the registry itself. */
void broker_destroy(struct broker *b);

/*
 * Adopt an accepted nonblocking descriptor as a new session in the
 * AWAITING_CONNECT state. Returns 0 on success (the broker now owns fd) and -1
 * on failure (fd is not closed and remains the caller's responsibility).
 */
int broker_accept(struct broker *b, int fd);

/*
 * Frame and handle every complete packet currently held in s's receive buffer,
 * consuming the bytes of each handled packet. Returns 0 when the session may
 * continue and -1 when the session was closed as a result of its input (the
 * caller must then reap and re-synchronize its interest mask).
 */
int broker_process_input(struct broker *b, struct session *s);

/*
 * The peer closed its write side or a read error occurred: process every
 * complete packet still buffered (so a final PUBLISH is still routed), then
 * close after the queued output has been flushed. Any trailing partial packet
 * bytes are discarded.
 */
void broker_session_eof(struct broker *b, struct session *s);

/*
 * Finish and remove sessions: a CLOSING session with empty queued output is
 * closed, then every CLOSED session is destroyed and removed from the registry.
 */
void broker_reap(struct broker *b);

/* Number of sessions currently in the registry. */
size_t broker_session_count(const struct broker *b);

/* Borrowed session at index, NULL when index is out of range. */
struct session *broker_session_at(const struct broker *b, size_t index);

#endif /* MQTT_BROKER_BROKER_H */
=== loop.h ===
/*
 * loop.h - epoll level-triggered execution layer for the broker.
 *
 * Descriptor modes and readiness preconditions
 * --------------------------------------------
 * The listener descriptor is created by net_listen() and the peer descriptors
 * by net_accept(); both are O_NONBLOCK|FD_CLOEXEC before they reach this layer,
 * so the accept path never depends on inheriting the listener's flags.
 *
 * Every descriptor is registered level-triggered. The listener is registered
 * with event data pointer NULL; every session descriptor is registered with its
 * struct session pointer as the data pointer.
 *
 *   - A read pump is dispatched ONLY when the returned event contains
 *     EPOLLIN, EPOLLRDHUP, EPOLLHUP or EPOLLERR, and only while the session is
 *     in AWAITING_CONNECT or READY. EPOLLOUT alone never permits a read.
 *   - A write pump is dispatched only when the event contains EPOLLOUT and the
 *     session already has queued output; EPOLLOUT while idle is ignored.
 *   - Readiness is recomputed after every dispatched event: a session is
 *     registered for EPOLLIN while it may still accept protocol input and for
 *     EPOLLOUT while its queued output is non-empty. Queued output is therefore
 *     always delivered to an idle recipient that sends nothing further.
 *   - Work per descriptor per event batch is bounded (read/write calls and
 *     accepted peers per listener), so one unread peer cannot stall another.
 *
 * Stopping: a signal handler may only store a value into a volatile
 * sig_atomic_t object handed to loop_set_stop_flag(); loop_run() observes that
 * flag and also loop_stop(), and returns so that ordinary code performs all
 * cleanup.
 *
 * Ownership: the loop borrows the broker and the listener descriptor. Neither
 * is closed or destroyed by loop_destroy(); the caller destroys the broker and
 * closes the listener after loop_destroy().
 */
#ifndef MQTT_BROKER_LOOP_H
#define MQTT_BROKER_LOOP_H

#include <signal.h>
#include <stddef.h>

#include "broker.h"

/* Opaque reactor instance. */
struct loop;

/*
 * Create a reactor bound to broker. Returns 0 on success and -1 on failure
 * (invalid argument or epoll_create1 failure). The caller owns the loop.
 */
int loop_create(struct broker *broker, struct loop **out_loop);

/*
 * Register a nonblocking listener descriptor. Returns 0 on success and -1 on
 * failure; on failure the listener stays usable and owned by the caller.
 */
int loop_add_listener(struct loop *l, int listener_fd);

/*
 * Point the loop at a flag written only by a signal handler. Passing NULL
 * clears the pointer. The object must outlive the running loop.
 */
void loop_set_stop_flag(struct loop *l, volatile sig_atomic_t *stop_flag);

/*
 * Run until the stop flag is set, loop_stop() is called, or a fatal reactor
 * error occurs. Returns 0 for a clean stop and -1 on a fatal error.
 */
int loop_run(struct loop *l);

/* Request that a running loop_run() return after the current event batch. */
void loop_stop(struct loop *l);

/* Release the epoll descriptor and the loop object; does not touch the broker. */
void loop_destroy(struct loop *l);

#endif /* MQTT_BROKER_LOOP_H */
