import json,os,glob
def resolve(path):
    p,_,ptr=path.partition('#')
    full=os.path.join('/work',p)
    if not os.path.exists(full): return 'MISSING FILE '+p
    d=json.load(open(full))
    cur=d
    for tok in ptr.lstrip('/').split('/'):
        if isinstance(cur,list):
            try: cur=cur[int(tok)]
            except Exception as e: return 'BAD IDX %s in %s'%(tok,path)
        else:
            if tok not in cur: return 'BAD KEY %s in %s'%(tok,path)
            cur=cur[tok]
    return cur
