/* LITERAL transcription of the SAVED src/topic.c/topic_filter_matches LOGIC steps (a)-(f) */
static int saved_matches(const char *f, size_t fl, const char *t, size_t tl){
    size_t fi=0, ti=0;
    if(!f||!t) return 0;
    if(fl==0||tl==0) return 0;
    if(t[0]==0x24 && (f[0]==0x23||f[0]==0x2B)) return 0;
    for(;;){
        size_t fj, tj;
        for(fj=fi; fj<fl && f[fj]!='/'; fj++){}
        if(fj-fi==1 && f[fi]=='#') return 1;                 /* (a) */
        for(tj=ti; tj<tl && t[tj]!='/'; tj++){}              /* (b) */
        if(!(fj-fi==1 && f[fi]=='+')){                       /* (c) */
            if((fj-fi)!=(tj-ti)) return 0;
            if(memcmp(f+fi,t+ti,fj-fi)!=0) return 0;
        }
        if(fj==fl && tj==tl) return 1;                        /* (d) */
        if(fj==fl) return 0;                                  /* (e) */
        if(tj==tl) return 0;                                  /* (e) BUG for '#'
