'F008 SUBACK pid=0x0102, one filter':((9<<4)|0,[0x01,0x02,0x00],3,[144,3,1,2,0]),
'F008 SUBACK pid=0xffff, two filters':((9<<4)|0,[255,255,0,0],4,[144,4,255,255,0,0]),
'F010 QoS0 PUBLISH topic=a payload=00ff':((3<<4)|0,[0,1,ord('a'),0,255],5,[48,5,0,1,97,0,255]),
'F013 PINGREQ':(F['F013']['values']['pingreq_wire_bytes'][0],[],F['F013']['values']['pingreq_wire_bytes'][1],[192,0]),
'F013 PINGRESP':(F['F013']['values']['pingresp_wire_bytes'][0],[],F['F013']['values']['pingresp_wire_bytes'][1],[208,0]),
'F014 DISCONNECT':(F['F014']['values']['wire_bytes'][0],[],F['F014']['values']['wire_bytes'][1],[224,0]),
}
for name,(b,body,rl,actual) in checks.items():
