maximum=F['F002']['values']['maximum']; enc=[]; n=maximum
while n>=128: enc.append((n&127)|128); n >>=7
enc.append(n)
print('F002 Remaining Length maximum: 268435455 = 127 + 127*128 + 127*128^2 + 127*128^3; computed encoding=',enc,'actual fact max_encoding=',F['F002']['values']['max_encoding'])
assert enc==F['F002']['values']['max_encoding']==[255,255,255,127]
for n in [0,2,3,4,5,127,128,65535,268435455]:
