import glob,json,os,re
for p in sorted(glob.glob('/work/functions/*.json')):
 d=json.load(open(p))
 for i,v in enumerate(d.get('TEST_VECTORS',[])):
  for where,obj in [('INPUT',v.get('INPUT',{})),('EXPECT',v.get('EXPECT',{}))]:
   def walk(x,path=''):
    if isinstance(x,dict):
     for k,val in x.items(): yield from walk(val,path+'/'+k)
    elif isinstance(x,list):
     for j,val in enumerate(x): yield from walk(val,path+f'/{j}')
    elif isinstance(x,str) and ('hex' in path.lower() or path.lower().endswith('/hex')):
     yield path,x
   for path,s in walk(obj):
    # Hex-only byte string candidates. Skip symbolic placeholders.
    t=s.strip().replace('[','').replace(']','')
    if re.fullmatch(r'(?:[0-9A-Fa-f]{2}(?:\s+|$))+',t):
     b=bytes.fromhex(t)
     if len(b)>=2 and b[0]>>4 in range(1,15):
      # parse mqtt remaining length
      val=0; mul=1; pos=1
      while pos<len(b) and pos<=4:
       c=b[pos]; val+=(c&127)*mul; pos+=1; mul*=128
       if c<128: break
      else: continue
      if pos+val!=len(b): print(os.path.basename(p),i,v['NAME'],where+path, s, 'bytes',len(b),'header',pos,'RL',val,'expected total',pos+val)
