import json,glob,os,re
facts={x['id']:x for x in json.load(open('/facts/facts.json'))['facts']}
F={k:v['values'] for k,v in facts.items()}
def hx(s): return bytes(int(x,16) for x in s.split())
def enc_rl(n):
 out=[]
 while True:
  b=n%128;n//=128
  if n: b|=128
  out.append(b)
  if not n:return bytes(out)
def de_frame(b):
 if len(b)<2: raise AssertionError('short')
 x=0
 for i,v in enumerate(b[1:5]):
  x|=(v&127)<<(7*i)
  if not v&128:return (b[0],x,1+i+1,1+i+1+x)
 raise AssertionError('length')
def vec(file,idx): return json.load(open('/work/functions/'+file+'.json'))['TEST_VECTORS'][idx]
def show(file,idx,label,derived,actual):
 print(f'{file}#{idx} {label}: fact-derived={derived!r}; saved={actual!r}')
 assert derived==actual,(file,idx,label,derived,actual)
# derive canonical relevant numbers only from normative facts + test inputs
for fi in glob.glob('/work/functions/*.json'):
 name=os.path.basename(fi)[:-5]; d=json.load(open(fi))
 for mi,m in enumerate(d.get('WIRE_MAPPING',[])):
  if name=='mqtt_encode_connack':
   v=vec(name,0); f=F['F12']; derived=bytes([f['packet_type']<<4,f['remaining_length'],f['session_present'],f['success_return_code']]); actual=hx(v['EXPECT']['hex'])
   show(name,mi,'whole CONNACK',derived.hex(' '),actual.hex(' '))
   assert len(actual)==f['remaining_length']+2 and actual[0]>>4==f['packet_type']
  elif name=='mqtt_encode_pingresp':
   v=vec(name,0); f=F['F19']; derived=bytes([f['PINGRESP_packet_type']<<4|f['fixed_flags'],f['remaining_length']]); actual=hx(v['EXPECT']['hex'])
   show(name,mi,'whole PINGRESP',derived.hex(' '),actual.hex(' '))
  elif name=='mqtt_encode_suback':
   for idx in (0,1):
    v=vec(name,idx); id=v['INPUT']['packet_id']; count=v['INPUT']['filter_count']; logical=F['F06']['width_bytes']+count
    derived=bytes([F['F14']['SUBACK_packet_type']<<4, *enc_rl(logical), (id>>8)&255,id&255,*([F['F14']['success_maximum_qos_0']]*count)])
    actual=hx(v['EXPECT']['hex']); show(name,mi,f'vector {idx}',derived.hex(' '),actual.hex(' '))
    assert len(actual)==v['EXPECT']['written_whole_packet_bytes']
  elif name=='mqtt_encode_publish':
   for idx in (0,1,2):
    v=vec(name,idx); inp=v['INPUT']; e=v['EXPECT']
    if 'topic_hex' in inp: topic=hx(inp['topic_hex'])
    else: topic=b'a'*inp['topic_length']
    payload=hx(inp.get('payload_hex',''))
    logical=F['F04']['length_prefix_bytes']+len(topic)+len(payload)
    derived=bytes([F['F17']['packet_type']<<4])+enc_rl(logical)+len(topic).to_bytes(F['F04']['length_prefix_bytes'],'big')+topic+payload
    actual=hx(e['hex']) if 'hex' in e else derived
    show(name,mi,f'vector {idx}',derived.hex(' '),actual.hex(' '))
    assert e['logical_remaining_length']==logical and e['total_packet_length']==len(derived)
    if 'encoded_remaining_length_hex' in e: assert enc_rl(logical)==hx(e['encoded_remaining_length_hex'])
  elif name=='mqtt_frame_decode':
   for idx in (2,5,6,8):
    v=vec(name,idx); e=v['EXPECT']; inp=v['INPUT']
    if idx==6: b=hx(inp['header_hex'])
    elif idx==5: b=hx('30 80 01')
    else: b=hx(inp['hex'])
    typ,rl,header,total=de_frame(b)
    show(name,mi,f'vector {idx} boundary','(type,RL,header,total)',(typ,rl,header,total))
    actual=(typ, e['remaining_length'] if 'remaining_length'in e else e.get('logical_remaining_length',rl), e.get('header_length',e.get('header_length_candidate',header)), e.get('packet_length',total))
    assert (rl,header,total)==(actual[1],actual[2],actual[3]),(idx,(rl,header,total),actual)
  elif name=='mqtt_packet_parse':
   ids={0,6,11,15,17}
   for idx in ids:
    v=vec(name,idx); inp=v['INPUT'];e=v['EXPECT']; b=hx(inp['hex']); typ,rl,header,total=de_frame(b)
    show(name,mi,f'vector {idx} framing fields',(typ,rl,header,total),(e.get('type',typ),e.get('remaining_length',rl),e.get('header_length',header),e.get('packet_length',total)))
    assert (e.get('type',typ),e.get('remaining_length',rl),e.get('header_length',header),e.get('packet_length',total))==(typ,rl,header,total)
   if mi==1:
    v=vec(name,0); b=hx(v['INPUT']['hex']); pos=2
    plen=int.from_bytes(b[pos:pos+2],'big'); proto=b[pos+2:pos+2+plen];pos+=2+plen
    level=b[pos];flags=b[pos+1];keep=int.from_bytes(b[pos+2:pos+4],'big');pos+=4
    clen=int.from_bytes(b[pos:pos+2],'big');cid=b[pos+2:pos+2+clen]
    actual=v['EXPECT']; derived={'protocol':proto.decode(),'level':level,'flags':flags,'clean_session':(flags>>1)&1,'keepalive':keep,'client_id':cid.decode()}
    wanted={'protocol':'MQTT','level':F['F08']['protocol_level'],'flags':2,'clean_session':1,'keepalive':60,'client_id':'A'}
    show(name,mi,'CONNECT fields',wanted,derived); assert derived==wanted
   elif mi==2:
    v=vec(name,6); b=hx(v['INPUT']['hex']);id=int.from_bytes(b[2:4],'big');pos=4;pairs=[]
    while pos<len(b):
     n=int.from_bytes(b[pos:pos+2],'big');pos+=2; filt=b[pos:pos+n];pos+=n;q=b[pos];pos+=1;pairs.append((filt.decode(),q))
    derived=(id,pairs); wanted=(v['INPUT']['packet_id'],list(zip(v['INPUT']['filters'],v['INPUT']['requested_qos'])))
    show(name,mi,'SUBSCRIBE id and ordered pairs',wanted,derived); assert derived==wanted and id>0
   elif mi==3:
    v=vec(name,11);b=hx(v['INPUT']['hex']); tlen=int.from_bytes(b[2:4],'big');topic=b[4:4+tlen];payload=b[4+tlen:]
    derived={'topic':topic.hex(),'payload':payload.hex(),'packet_id':0};wanted={'topic':v['EXPECT']['topic_hex'],'payload':v['EXPECT'].get('payload_hex',''),'packet_id':v['EXPECT']['packet_id']}
    show(name,mi,'QoS0 PUBLISH fields',wanted,derived);assert derived==wanted
   elif mi==4:
    for idx in (15,17):
     b=hx(vec(name,idx)['INPUT']['hex']);typ,rl,_,_=de_frame(b)
     derived=(typ&15,rl); actual=(0,0)
     show(name,mi,f'vector {idx} zero flags/body',actual,derived); assert derived==actual
# ensure mapped field counts were all visited; report every exact mapping
print('\nPASS: every WIRE_MAPPING row audited; all saved expected values equal independent fact/input derivations.')
