import json
for p,typ in [('/work/functions/mqtt_topic_filter_valid.json','filter'),('/work/functions/mqtt_topic_name_valid.json','topic')]:
 d=json.load(open(p))
 for i,v in enumerate(d['TEST_VECTORS']):
  x,e=v['INPUT'],v['EXPECT']
  if 'filters' in x: cases=[s.encode() for s in x['filters']]
  elif 'filter' in x: cases=[x['filter'].encode()]
  elif 'filters_hex' in x: cases=[bytes.fromhex(s) for s in x['filters_hex']]
  elif 'lengths' in x: cases=[b'a'*z for z in x['lengths']]
  elif 'length' in x: cases=[b'a'*x['length']]
  elif 'hex' in x: cases=[bytes.fromhex(x['hex'])]
  elif 'topic' in x: cases=[x['topic'].encode()]
  elif 'topic_values' in x: cases=[s.encode() for s in x['topic_values']]
  elif 'hex_values' in x: cases=[bytes.fromhex(s) for s in x['hex_values']]
  else: continue
  outs=[]
  for b in cases:
   ok=bool(b) and len(b)<=65535 and b'\0' not in b
   try:b.decode('utf8')
   except UnicodeDecodeError:ok=False
   if typ=='filter':
    lv=b.split(b'/')
    for j,l in enumerate(lv):
     if b'+' in l and l!=b'+':ok=False
     if b'#' in l and (l!=b'#' or j!=len(lv)-1):ok=False
   else:
    if b'+' in b or b'#' in b:ok=False
   outs.append(int(ok))
  expected=e.get('return_values')
  if expected is None:
   expected=[e['return']]*len(cases)
  assert outs==expected,(p,i,outs,expected)
  print(f'{p}#/TEST_VECTORS/{i}: cases={len(cases)} replay={outs} EXPECT={expected}; input={x}')
print('PASS all filter/topic validity vectors')
