  b=bytes.fromhex(x.get('hex','')); available=x.get('available',len(b)); virtual=False
 if available==0 or len(b)<2: status='MQTT_FRAME_INCOMPLETE'
 else:
  val=0; shift=0; groups=0; pos=1
  while True:
   if pos>=len(b): status='MQTT_FRAME_INCOMPLETE'; break
   octet=b[pos]; pos+=1; groups+=1
   val|=(octet&127)<<shift
   if not octet&128: break
   if groups==4: status='MQTT_FRAME_INVALID'; break
   shift+=7
  if status is None:
   hdr=1+groups; whole=hdr+val
   if available<whole: status='MQTT_FRAME_INCOMPLETE'
   else: status='MQTT_FRAME_COMPLETE'; rl=val
 print(f'{p}#/TEST_VECTORS/{i} {v["NAME"]}: encoded_header={b[:5].hex(" ").upper()} available={available} => branch result={status}, groups={groups if available and len(b)>1 else 0}, logical_RL={rl}, header={hdr}, whole_frame={whole}; saved EXPECT={e}')
